from bausteine_basis import i, IC

def _btn(ic, lab=''):
    return f'<button type="button" class="km-iconbtn{" km-iconbtn--label" if lab else ""}" aria-label="{lab or ic}">{lab}{i(ic)}</button>'

_akt = '<td class="km-table__actions"><span class="km-table__actions-row">' + _btn('bookmark') + _btn('star') + _btn('copy', 'Claude') + '</span></td>'

def _zeile(n, name, typ, datum, rel, pct, farbe, std):
    return (f'<tr><td><a class="km-table__name" href="#tabelle-spalten"><span class="km-monogram" style="--km-monogram-color:var(--km-color-accent)">{n}</span>{name}</a></td><td>{typ}</td>'
            f'<td class="km-table__date">{datum}<span class="km-table__date-rel">({rel})</span><div class="km-table__activity"><div class="km-table__activity-fill" style="width:{pct}%;background:var({farbe})"></div></div></td>'
            f'<td class="km-table__hours">{std}</td><td class="km-table__text">Kurzbeschreibung, die als Fließtext umbrechen darf, ohne die Spalte zu sprengen.</td>' + _akt + '</tr>')

