# Fünfzehnter Nachtrag (2026-11-09, 0.10.0): Fragebogen-Bausteine aus dem Neubau von Startklar
def _antwort(name, werte, gewaehlt=None):
    t = {'ja': ('ok', 'check'), 'nein': ('danger', 'x'), 'offen': ('warn', 'circle-question-mark'), 'sperrt': ('danger', 'octagon-x'), 'sperrt nicht': ('ok', 'check'), 'grün': ('ok', ''), 'gelb': ('warn', ''), 'rot': ('danger', '')}
    out = '<div class="km-answer" role="radiogroup" aria-label="Antwort">'
    for w in werte:
        ton, ic = t[w]
        zeichen = i(ic, 'km-answer__sign') if ic else '<span class="km-answer__swatch" aria-hidden="true"></span>'
        out += (f'<label class="km-answer__opt km-answer__opt--{ton}" title="{w}"><input type="radio" name="{name}" value="{w}"{" checked" if w == gewaehlt else ""}>'
                f'<span class="km-answer__face">{zeichen}{i("rotate-ccw", "km-answer__reset")}<span class="kern-sr-only">{w}</span></span></label>')
    return out + '</div>'

